<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Shared\Security\PasswordHasher;
use PHPUnit\Framework\TestCase;

final class PasswordHasherUnitTest extends TestCase
{
    /**
     * Cheap argon2id options to keep the suite fast.
     */
    private const array FAST = ['memory_cost' => 1024, 'time_cost' => 1, 'threads' => 1];

    public function test_hash_is_argon2id_and_salted(): void
    {
        $hasher = new PasswordHasher(self::FAST);

        $one = $hasher->hash('s3cret');
        $two = $hasher->hash('s3cret');

        $this->assertStringStartsWith(PasswordHasher::HASH_PREFIX, $one);
        $this->assertNotEquals($one, $two);
        $this->assertStringNotContainsString('s3cret', $one);
    }

    public function test_verify_hash(): void
    {
        $hasher = new PasswordHasher(self::FAST);
        $stored = $hasher->hash('s3cret');

        $this->assertTrue($hasher->verify('s3cret', $stored));
        $this->assertFalse($hasher->verify('S3cret', $stored));
        $this->assertFalse($hasher->needsRehash($stored));
    }

    public function test_non_hash_values_never_verify(): void
    {
        $hasher = new PasswordHasher(self::FAST);

        $this->assertFalse($hasher->verify('s3cret', 's3cret'));
        $this->assertFalse($hasher->verify('s3cret', 'cyphered://abc'));
    }

    public function test_needs_rehash_when_options_change(): void
    {
        $stored = (new PasswordHasher(self::FAST))->hash('s3cret');
        $stronger = new PasswordHasher(['memory_cost' => 2048, 'time_cost' => 1, 'threads' => 1]);

        $this->assertTrue($stronger->verify('s3cret', $stored));
        $this->assertTrue($stronger->needsRehash($stored));
    }

    public function test_supported_formats(): void
    {
        $this->assertTrue(PasswordHasher::isSupported('$argon2id$v=19$m=1024,t=1,p=1$abc'));
        $this->assertFalse(PasswordHasher::isSupported('cyphered://abc'));
        $this->assertFalse(PasswordHasher::isSupported('plain'));
        $this->assertFalse(PasswordHasher::isSupported('$2y$10$bcrypt'));
    }
}
